type TerminateContractParams struct {
	TerminationReason        *string     `json:"termination_reason"`
	TerminationEffectiveDate pgtype.Date `json:"termination_effective_date"`
	OrgID                    pgtype.UUID `json:"org_id"`
	ID                       pgtype.UUID `json:"id"`
}

func (q *Queries) TerminateContract(ctx context.Context, arg TerminateContractParams) (Contract, error) {
	row := q.db.QueryRow(ctx, terminateContract,
		arg.TerminationReason,
		arg.TerminationEffectiveDate,
		arg.OrgID,
		arg.ID,
	)
	var i Contract
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.UnitID,
		&i.RenterUserID,
		&i.TemplateID,
		&i.TermsSnapshotHtml,
		&i.RentAmount,
		&i.RentPeriodDays,
		&i.PaymentPeriodID,
		&i.PaymentPeriodDays,
		&i.TermDays,
		&i.StartDate,
		&i.EndDate,
		&i.DueDay,
		&i.Status,
		&i.SnapshotHash,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.ActivatedAt,
		&i.TerminatedAt,
		&i.TerminationReason,
		&i.TerminationEffectiveDate,
		&i.LinkRequestID,
		&i.Language,
	)
	return i, err
}
